import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as s,o as t,af as a,b as l,w as o,a as d,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse(`{"title":"Production","description":"A working feature is not a launchable product — this group turns 'it demos' into 'it operates' with six evidence chains: testing, evaluation, observability, security, cost, and deployment.","frontmatter":{"title":"Production","description":"A working feature is not a launchable product — this group turns 'it demos' into 'it operates' with six evidence chains: testing, evaluation, observability, security, cost, and deployment.","domain":"tech","tags":["tech","operations"],"navOrder":80,"topicId":"operations-index","layer":"8","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["agent-recovery-hitl"],"next":["testing","evaluation","observability","security","cost-performance","deployment","resources","agentops"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/08-production/index.md","filePath":"tech/08-production/index.md","lastUpdated":1791123418000}`),u={name:"tech/08-production/index.md"};function p(m,e,g,b,f,y){const n=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<blockquote><p><strong>Group</strong>: Production | <strong>Previous group exit</strong>: can restrict permissions, pause/resume tasks | <strong>This group exit</strong>: can substantiate quality, risk, performance, rollback, and ownership with replayable evidence <strong>Prerequisites</strong>: <a href="./../06-agent-systems/recovery-hitl.html">Recovery and Human-in-the-Loop</a> | <strong>Next</strong>: <a href="./testing.html">Testing</a>, <a href="./evaluation.html">Evaluation (Bridge)</a>, <a href="./observability.html">Observability</a>, <a href="./security.html">Security</a>, <a href="./cost-performance.html">Cost and Performance</a>, <a href="./deployment.html">Deployment and Release</a>; after this group, the <a href="./../../resources.html">Resource Library</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>BLUF</strong>: Between &quot;the feature works&quot; and &quot;we can run this in production&quot; lies an entire group&#39;s worth of work. A demo needs one success; operations need <strong>replayable evidence</strong> — the ability to reconstruct what happened during an incident, to predict the impact of a change, and to point at a rollback path and an owner. This group consolidates the engineering of the upstream groups into five kinds of launch evidence: quality, risk, performance, rollback, and ownership.</p><h3 id="mental-model-six-evidence-chains" tabindex="-1">Mental model: six evidence chains <a class="header-anchor" href="#mental-model-six-evidence-chains" aria-label="Permalink to &quot;Mental model: six evidence chains&quot;">​</a></h3>',4)),(t(),l(c,null,{default:o(()=>[h(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20Q%5B%22Production%20group%20question%3A%20how%20do%20we%20prove%20it%20can%20launch%20and%20keep%20running%3F%22%5D%0A%20%20%20%20Q%20--%3E%20T%5B%22Testing%3Cbr%2F%3Edeterministic%2C%20assertable%20behavior%22%5D%0A%20%20%20%20Q%20--%3E%20E%5B%22Evaluation%20(bridge)%3Cbr%2F%3Eprobabilistic%20quality%20%E2%86%92%20evals%20site%22%5D%0A%20%20%20%20Q%20--%3E%20O%5B%22Observability%3Cbr%2F%3Ereplayable%2C%20attributable%20traces%22%5D%0A%20%20%20%20Q%20--%3E%20S%5B%22Security%3Cbr%2F%3Eengineered%20boundaries%20for%20three%20risk%20layers%22%5D%0A%20%20%20%20Q%20--%3E%20C%5B%22Cost%20%26%20performance%3Cbr%2F%3Eunit%20economics%20and%20latency%20breakdown%22%5D%0A%20%20%20%20Q%20--%3E%20D%5B%22Deployment%20%26%20release%3Cbr%2F%3Egates%2C%20rollback%2C%20runbook%22%5D%0A%20%20%20%20T%20%26%20E%20%26%20O%20%26%20S%20%26%20C%20%26%20D%20--%3E%20X%5B%22Exit%3A%20quality%20%2F%20risk%20%2F%20performance%20%2F%3Cbr%2F%3Erollback%20%2F%20ownership%20%E2%80%94%20evidence%20complete%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The six chains are not six sequential stages; they are six facets of the same artifacts. One trace is simultaneously observability evidence, cost evidence, and incident-replay material.</p><h3 id="symptom-routing-table" tabindex="-1">Symptom routing table <a class="header-anchor" href="#symptom-routing-table" aria-label="Permalink to &quot;Symptom routing table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom (&quot;the feature works, but…&quot;)</th><th>Go to</th><th>Evidence you gain</th></tr></thead><tbody><tr><td>Change one prompt, no idea what broke</td><td><a href="./testing.html">Testing</a></td><td>Deterministic test pyramid: assertable blast radius</td></tr><tr><td>&quot;Better/worse&quot; is only a vibe</td><td><a href="./evaluation.html">Evaluation (Bridge)</a></td><td>Golden set + threshold as a release gate (methodology → evals site)</td></tr><tr><td>Production incident, only scattered logs to guess from</td><td><a href="./observability.html">Observability</a></td><td>Replayable trace/span + correlation ID</td></tr><tr><td>Worried about injection, overreach, leaks, but &quot;the model will refuse&quot;</td><td><a href="./security.html">Security</a></td><td>Combined defense: input filter + permission boundary + output scanner</td></tr><tr><td>Nobody can explain the monthly bill or P95 latency</td><td><a href="./cost-performance.html">Cost and Performance</a></td><td>Per-request cost tracking + latency breakdown + optimization ladder</td></tr><tr><td>Releases by manual copy, rollback by memory</td><td><a href="./deployment.html">Deployment and Release</a></td><td>Gate chain, versioned rollback, runbook</td></tr></tbody></table><h3 id="decision-table-how-each-evidence-type-is-obtained" tabindex="-1">Decision table: how each evidence type is obtained <a class="header-anchor" href="#decision-table-how-each-evidence-type-is-obtained" aria-label="Permalink to &quot;Decision table: how each evidence type is obtained&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Evidence type</th><th>Direction</th><th>Control</th><th>State</th><th>Trust domain</th><th>Minimum complexity</th></tr></thead><tbody><tr><td>Quality (testing + eval)</td><td>Read</td><td>You write assertions/datasets</td><td>Fixtures + golden set</td><td>Inside CI</td><td>One node:test file</td></tr><tr><td>Risk (security)</td><td>Read/Write</td><td>Filters + permission boundary + audit</td><td>Rules + audit log</td><td>Application trust domain</td><td>One layer of I/O filtering</td></tr><tr><td>Performance (cost + latency)</td><td>Read</td><td>Sampling &amp; budget config</td><td>Time series</td><td>Observability backend</td><td>Per-request usage accounting</td></tr><tr><td>Rollback (deployment)</td><td>Write</td><td>Version + traffic switch</td><td>Versioned artifacts</td><td>Deployment trust domain</td><td>Version number + dual-write switch</td></tr><tr><td>Ownership (runbook)</td><td>—</td><td>Roster + escalation path</td><td>Docs + alert routing</td><td>Organization</td><td>One page of who owns what</td></tr></tbody></table><h3 id="cross-cutting-statement" tabindex="-1">Cross-cutting statement <a class="header-anchor" href="#cross-cutting-statement" aria-label="Permalink to &quot;Cross-cutting statement&quot;">​</a></h3><p>Security, cost, and observability <strong>do not first appear in this group</strong>: permission boundaries are introduced in <a href="./../05-action/tool-execution.html">Tool Execution</a>, token usage arrives with the usage field of the <a href="./../02-inference-interface/model-api.html">Model API</a>, redaction matters as soon as <a href="./../03-context/context-engineering.html">Context Engineering</a> begins. The upstream groups handle these concerns locally in their own scenarios; <strong>the Production group consolidates them into systematic launch evidence</strong> — no longer &quot;done right somewhere&quot;, but &quot;provable everywhere&quot;.</p><h3 id="when-to-use-when-not-to" tabindex="-1">When to use / when not to <a class="header-anchor" href="#when-to-use-when-not-to" aria-label="Permalink to &quot;When to use / when not to&quot;">​</a></h3><ul><li>Use: any system crossing from &quot;personal demo&quot; to &quot;has users, has on-call, has a bill&quot;.</li><li>Do not use: one-off scripts, local experiments, learning toys — building five evidence chains for them is over-engineering. Judge with the <a href="./../00-map/complexity-ladder.html">Complexity Decision Ladder</a>.</li></ul><p>Historical milestone: this group&#39;s structure was frozen in 2026-09 with Issue #116, upgrading and merging the legacy <code>engineering/</code> pages (testing/evals/observability/security/cost-optimization) plus the <code>testing/</code> and <code>evaluation/</code> directories; earlier provenance unverified, not fabricated.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This page is the routing layer and has no runnable artifact; &quot;usage&quot; = a launch-readiness self-audit (on paper, ≤15 min). Acceptance: for the system you want to launch, every one of the five evidence types resolves to &quot;concrete artifact + named owner&quot; — any blank cell is your gap.</p><h3 id="drill-the-five-question-audit" tabindex="-1">Drill: the five-question audit <a class="header-anchor" href="#drill-the-five-question-audit" aria-label="Permalink to &quot;Drill: the five-question audit&quot;">​</a></h3><p>Answer each question for the target system; record &quot;where the evidence lives (file/dashboard/doc)&quot; and &quot;who owns it&quot;:</p><ol><li><strong>Quality</strong>: on the last prompt change, which tests ran in CI? How much did the eval score move? (→ <a href="./testing.html">Testing</a> / <a href="./evaluation.html">Evaluation</a>)</li><li><strong>Risk</strong>: an injection payload hits your input endpoint — which layer blocks it, and where is the block logged? (→ <a href="./security.html">Security</a>)</li><li><strong>Performance</strong>: pick a random production request from yesterday — can you find its token cost and per-segment latency within a minute? (→ <a href="./observability.html">Observability</a> / <a href="./cost-performance.html">Cost and Performance</a>)</li><li><strong>Rollback</strong>: what is the previous version of the current one? Which exact actions switch back to it? (→ <a href="./deployment.html">Deployment and Release</a>)</li><li><strong>Ownership</strong>: at 2 a.m. the model vendor returns 5xx — which dashboard does the on-call look at first, and what is the first action? (→ the runbook in <a href="./deployment.html">Deployment and Release</a>)</li></ol><h3 id="usage-boundary" tabindex="-1">Usage boundary <a class="header-anchor" href="#usage-boundary" aria-label="Permalink to &quot;Usage boundary&quot;">​</a></h3><ul><li>This group does not teach &quot;how to test / how to instrument&quot; — that is the six sub-chapters&#39; job; this page only routes symptoms to the right evidence chain.</li><li>The <strong>depth</strong> of each evidence type scales with business risk: an internal tool does not need bank-grade audit logs, but it does need the minimum version that answers the five questions.</li></ul><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-consolidation-happens-in-the-production-group" tabindex="-1">Why consolidation happens in the Production group <a class="header-anchor" href="#why-consolidation-happens-in-the-production-group" aria-label="Permalink to &quot;Why consolidation happens in the Production group&quot;">​</a></h3><p>Every upstream group exits on &quot;it works&quot;: the schema validates, the interaction is cancellable end to end, retrieval is traceable, permissions pause and resume. But &quot;works&quot; is a <strong>single-run property</strong>; operations demand a <strong>continuing property</strong> — the ten-thousandth request as reliable as the first, the tenth change as predictable as the first. The instrument that upgrades single-run to continuing is evidence:</p><ul><li>Predictable behavior ← testing + evaluation (comparable before/after change)</li><li>Explainable failures ← observability (replayable traces)</li><li>Verifiable boundaries ← security (attack paths with block records)</li><li>Accountable spend ← cost &amp; performance (per-request accounting)</li><li>Reversible changes ← deployment (versions that switch back)</li></ul><h3 id="replayability-is-the-group-wide-invariant" tabindex="-1">Replayability is the group-wide invariant <a class="header-anchor" href="#replayability-is-the-group-wide-invariant" aria-label="Permalink to &quot;Replayability is the group-wide invariant&quot;">​</a></h3><p>All five evidence types share one acceptance criterion: <strong>it can be replayed afterwards</strong>. Tests can re-run, datasets can reproduce, traces can be exported and re-inspected, attack samples can be re-fired against the filter, costs can be recomputed per request, versions can be redeployed. Any observation of the form &quot;we saw it then, can&#39;t find it now&quot; is not evidence — that is the line between real observability and &quot;happened to see it&quot;.</p><h3 id="division-of-labor-with-external-owners" tabindex="-1">Division of labor with external owners <a class="header-anchor" href="#division-of-labor-with-external-owners" aria-label="Permalink to &quot;Division of labor with external owners&quot;">​</a></h3><p>This group deliberately stops at two places: evaluation methodology (datasets/scorers/judges/statistics/red-teaming) is owned by <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a> — this repo only answers &quot;when is evidence needed and how it plugs into the release gate&quot;; the mechanics of the model-alignment risk layer (reward hacking, jailbreak propensity) are owned by <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> — this repo only does application-side engineering. Details in <code>_phase0/bridge-register.md</code>.</p><h3 id="spec-vs-local-measurement" tabindex="-1">Spec vs local measurement <a class="header-anchor" href="#spec-vs-local-measurement" aria-label="Permalink to &quot;Spec vs local measurement&quot;">​</a></h3><p>This routing page has no spec to implement; each sub-chapter carries its own &quot;spec vs measured&quot; column (e.g. OTel GenAI conventions, the OWASP 2026 list, Vitest version requirements).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>This page has no code integration; &quot;development&quot; = using the five-question audit as a launch-review gate.</p><h3 id="symptom-→-evidence-→-action-→-done-when" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: review gets rejected with &quot;how do you prove it&#39;s correct?&quot; and the team can only replay the demo. <strong>Evidence</strong>: no five-question audit in the review materials; no reconcilable artifacts between change history and production behavior. <strong>Action</strong>: fill in the audit; for any blank cell, build the minimum version first (one test file, one trace, one page of runbook all count). <strong>Done when</strong>: the review materials contain the audit table with concrete artifact paths and named owners per row.</p><h3 id="symptom-→-evidence-→-action-→-done-when-1" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the incident postmortem runs three pages and concludes &quot;the model misbehaved&quot;. <strong>Evidence</strong>: no exportable trace in the incident window; request logs carry only status codes, no token usage or tool-call records. <strong>Action</strong>: add correlation-ID propagation and span recording per <a href="./observability.html">Observability</a>; put &quot;replay the incident window&quot; first in the postmortem template. <strong>Done when</strong>: the next similar incident starts its postmortem by exporting the window&#39;s traces instead of scrolling chat logs.</p><h3 id="symptom-→-evidence-→-action-→-done-when-2" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the bill doubles and nobody knows which feature, user, or request class caused it. <strong>Evidence</strong>: the only cost number is the vendor&#39;s monthly invoice; no per-request/per-feature usage accounting. <strong>Action</strong>: establish per-request cost tracking per <a href="./cost-performance.html">Cost and Performance</a> (usage field → record → aggregate); decomposition before optimization. <strong>Done when</strong>: the month&#39;s cost splits along &quot;feature × model × input/output/cache&quot; and you can name the largest item.</p><h3 id="anti-patterns" tabindex="-1">Anti-patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-patterns&quot;">​</a></h3><ul><li><strong>Evidence theater</strong>: screenshots and numbers assembled to pass review, not replayable afterwards — the Production-group form of &quot;looks successful but under-evidenced&quot;.</li><li><strong>All six chains, fully armed</strong>: bank-grade audit and full-rate trace sampling for an internal tool turns evidence cost into the new operational burden.</li><li><strong>Evidence detached from the system</strong>: tests run against mocks, traces enabled only in staging — the production path is exactly the uncovered one.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: read this page&#39;s routing table; run a five-question audit on your own system; find the largest gap.</li><li><strong>Builder</strong>: enter <a href="./testing.html">Testing</a> and <a href="./observability.html">Observability</a> — the two chains that compound first (change safety + explainable failures).</li><li><strong>Operator</strong>: enter <a href="./security.html">Security</a>, <a href="./cost-performance.html">Cost and Performance</a>, <a href="./deployment.html">Deployment and Release</a>; fold risk, spend, and rollback into daily routine.</li><li><strong>Researcher</strong>: read the L0/L1 specs below (OWASP, NIST, OTel) for the field&#39;s framing of &quot;reliable AI operations&quot;.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Evidence level</th><th>Canonical URL</th><th>Purpose</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>OWASP GenAI LLM Top 10 2026</td><td>L0 (official list)</td><td><a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/</a></td><td>Baseline for risk evidence</td><td>Published 2026-08-04; ranking calibrated on 7,714 real incidents (retrievedAt 2026-09-01)</td><td><a href="./security.html">Security</a></td></tr><tr><td>NIST AI RMF 1.0</td><td>L0 (official framework)</td><td><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></td><td>Voluntary governance framework</td><td>Released 2023-01-26, voluntary; GenAI Profile (NIST AI 600-1) 2024-07-26; NIST notes 1.0 is being revised under the White House AI Action Plan (retrievedAt 2026-09-01)</td><td><a href="./security.html">Security</a> governance section</td></tr><tr><td>OpenTelemetry GenAI semantic conventions</td><td>L0 (official spec)</td><td><a href="https://github.com/open-telemetry/semantic-conventions-genai" target="_blank" rel="noreferrer">https://github.com/open-telemetry/semantic-conventions-genai</a></td><td>Naming baseline for observability evidence</td><td>GenAI conventions moved to a dedicated repo in 2026-06; covers GenAI clients/MCP/provider conventions (retrievedAt 2026-09-01)</td><td><a href="./observability.html">Observability</a></td></tr><tr><td>evals site</td><td>sibling (cross-repo owner)</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>Sole owner of evaluation methodology</td><td>This repo keeps only release-gate integration (bridge-register 2026-09-01)</td><td><a href="./evaluation.html">Evaluation (Bridge)</a></td></tr></tbody></table><h3 id="falsification-and-open-questions" tabindex="-1">Falsification and open questions <a class="header-anchor" href="#falsification-and-open-questions" aria-label="Permalink to &quot;Falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if you find a real system that operates reliably while lacking one of the five evidence types, the necessity assumption for that type has a hole — first check whether it uses an equivalent evidence form outside this table, then consider revising this group&#39;s exit.</li><li>Open: how to grade the depth of the six chains by business risk (which scenarios may explicitly waive which evidence) — to be backfilled as sub-chapter runbooks accumulate cases.</li></ul><h3 id="learn-ai-stops-here-where-to-go-next" tabindex="-1">learn-ai stops here / where to go next <a class="header-anchor" href="#learn-ai-stops-here-where-to-go-next" aria-label="Permalink to &quot;learn-ai stops here / where to go next&quot;">​</a></h3><ul><li>Evaluation methodology, dataset construction, judges and statistics: <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>.</li><li>How model alignment and post-training shape risk behavior: <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>The full resource index after this group: <a href="./../../resources.html">Resource Library</a>.</li></ul>',46))])}const P=r(u,[["render",p]]);export{x as __pageData,P as default};
